<script lang="ts">
	import type { Component, Snippet } from 'svelte';
	import type { ModalButton } from './ModalTypes.js';
	import type { RenderFn } from '../types.js';

	/**
	 * Internal component for rendering modal content.
	 * Used by openModal() - not intended for direct use.
	 * Use <Modal> or <Dialog> instead.
	 * 
	 * Note: Focus trapping, ESC handling, and backdrop are provided
	 * by the parent <dialog> element, not by this component.
	 */
	let {
		children,
		text,
		snippet,
		render,
		component: Comp,
		props,
		buttons,
		buttonsConfig,
		close,
		title,
		shape = 'rounded',
		contained = true,
		unstyled = false,
	}: {
		children?: Snippet<[close: () => void]>;
		text?: string;
		snippet?: Snippet<[close: () => void]>;
		render?: RenderFn<[close: () => void]>;
		component?: Component;
		props?: any;
		buttons?: Snippet<[close: () => void]>;
		buttonsConfig?: ModalButton[];
		close: () => void;
		title?: string;
		shape?: 'rounded' | 'sharp';
		contained?: boolean;
		unstyled?: boolean;
	} = $props();

	const baseId = crypto.randomUUID();
	let titleId = $derived(title ? `modal-title-${baseId}` : undefined);
	let loading: Record<number, boolean> = $state({});

	async function handleButtonClick(btn: ModalButton, index: number) {
		if (!btn.onclick) {
			close();
			return;
		}
		const result = btn.onclick(close);
		if (result instanceof Promise) {
			loading[index] = true;
			try {
				await result;
			} finally {
				loading[index] = false;
			}
		}
	}
</script>

<div
	class="ModalContent {shape}"
	class:contained
	class:unstyled
	aria-labelledby={titleId}
>
	<div class="ModalContentArea">
		{#if title}
			<h2 id={titleId} class="ModalTitle">{title}</h2>
		{/if}
		{#if text}
			<p>{text}</p>
		{/if}
		{#if snippet}
			{@render snippet(close)}
		{:else if render}
			{@render render(close)}
		{/if}
		{#if Comp}
			<Comp {...props} {close} />
		{/if}
		{#if children}
			{@render children(close)}
		{/if}
	</div>
	{#if buttonsConfig}
		<div class="ModalActions">
			{#each buttonsConfig as btn, i}
				<button
					class="button {btn.variant || 'default'}"
					disabled={btn.disabled || loading[i]}
					onclick={() => handleButtonClick(btn, i)}
				>{btn.text}</button>
			{/each}
		</div>
	{:else if buttons}
		<div class="ModalActions">
			{@render buttons(close)}
		</div>
	{/if}
</div>

<style>
	.ModalContent {
		display: grid;
		grid-template-rows: 1fr auto;
		gap: var(--modal-gap);
		width: var(--modal-width, fit-content);
		min-width: var(--modal-min-width, auto);
		max-width: min(
			var(--modal-max-width, 40rem),
			calc(100svw - 2rem - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px))
		);
		max-height: min(
			var(--modal-max-height, 80svh),
			calc(100svh - 2rem - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px))
		);
		background: var(--modal-background, var(--surface-background));
		border: var(--modal-border-size) var(--modal-border-style) var(--modal-border-color);
		border-radius: var(--modal-border-radius, var(--surface-border-radius));
		box-shadow: var(--modal-shadow, var(--surface-shadow));
		overflow: hidden;
	}

	.ModalContent.sharp {
		border-radius: 0;
	}

	.ModalContent:not(.contained) {
		border: none;
	}

	.ModalContent.unstyled {
		background: transparent;
		border: none;
		box-shadow: none;
		max-width: none;
		max-height: none;
		display: block;
	}

	.ModalContentArea {
		overflow: auto;
		scrollbar-gutter: stable;
		scrollbar-width: thin;
		padding-block: var(--modal-padding-block);
		padding-inline: var(--modal-padding-inline);
		text-wrap: pretty;
	}

	.ModalContent.unstyled .ModalContentArea {
		padding: 0;
		overflow: visible;
	}

	.ModalTitle {
		margin-block-start: 0;
		margin-block-end: var(--space-md);
		font-size: var(--font-size-h4);
		font-weight: var(--font-weight-semibold);
		color: var(--text-color-heading);
		line-height: var(--font-line-height-heading);
	}

	.ModalContent.unstyled .ModalTitle {
		margin: 0;
	}

	.ModalActions {
		background: var(--modal-actions-background);
		border-top: var(--modal-border-size) var(--modal-border-style) var(--modal-actions-border-color);
		padding-block: var(--modal-actions-padding-block);
		padding-inline: var(--modal-actions-padding-inline);
		display: flex;
		gap: var(--space-sm);
		justify-content: flex-end;
		align-items: center;
	}

	.ModalContent.unstyled .ModalActions {
		background: transparent;
		border: none;
		padding: 0;
	}
</style>
